\label{defn:fixed} 
The \emph{guessing number} of $G$ with $s$ colours is defined as
	$$ \mbox{gn}(G,s) = \log_s \max_{\mathcal{P}} \left[ \mbox{fix}(\mathcal{P}) \right]. $$

\begin{equation}
	\label{eq:perfect_graphs}
	\mbox{gn}(C_3,s) = 2 \quad \mbox{and} \quad \mbox{gn}(C_{2k},s)=k \quad \forall \: k. 
	\end{equation}

