\label{prop:monotone}
Let $G$ be a graph, let $s$ and $s^\prime$ be positive integers with $s^\prime \leq s$, and let $\mathcal{P}$ be any protocol on $G$ with $s$ colours. There exists a protocol $\mathcal{P}^\prime$ on $G$ with $s^\prime$ colours such that 
	$$ \big\{ c \in \mbox{Fix}(\mathcal{P}) \: \big| \: 0 \leq c_i < s^\prime \: \forall i \big\} \subseteq \mbox{Fix}(\mathcal{P}^\prime). $$

If $\mathcal{P} = (f_1,f_2, \ldots f_n)$ then define $\mathcal{P}^\prime = (f_1^\prime,f_2^\prime, \ldots ,f_n^\prime )$ in the following way.
\begin{itemize}
\item If $0 \leq c_j<s^\prime$ for all $j$ such that $v_iv_j \in E$, and $0 \leq f_i(c)<s^\prime$ then $f_i^\prime(c) = f_i(c)$.
\item If $s^\prime \leq c_j < s$ for any $j$ such that $v_iv_j \in E$, or $s^\prime \leq f_i(c) < s$ then $f_i^\prime(c) = 0$.
\end{itemize}
For any colouring $c \in \mbox{Fix}(\mathcal{P})$, if $0 \leq c_i < s^\prime$ for all $i$, then $\mathcal{P}^\prime(c) = \mathcal{P}(c) = c$ so $c \in \mbox{Fix}(\mathcal{P}^\prime)$.

\label{defn:entropy}
Let $A_1, \ldots, A_k$ be random variables which take values in a finite set $\mathcal{A}$. The \emph{entropy} of $A_1,\ldots, A_k$ is denoted $H(A_1,\ldots, A_k)$ and is given by:
	$$ H(A_1,\ldots,A_k) = -\sum_{a_1,\ldots,a_k \in \mathcal{A}^k} \mathbb{P}(A_1=a_1,\ldots,A_k=a_k) \log_s \mathbb{P}(A_1=a_1,\ldots,A_k=a_k). $$	
The \emph{mutual information} of $A_1$ and $A_2$ is denoted $I(A_1;A_2)$ and is given by: 
	$$ I(A_1;A_2) = H(A_1) + H(A_2) - H(A_1,A_2). $$
	Let $B$ be another random variable taking values in $\mathcal{A}$. The conditional mutual information of $I(A_1;A_2|B)$ is given by
	\begin{equation}
	I(A_1;A_2|B) = H(A_1,B) + H(A_2,B) - H(A_1,A_2,B) - H(B).
	\label{eq:conditional_mutual_information}
	\end{equation}

\begin{equation}
	I(A_1;A_2|B) = H(A_1,B) + H(A_2,B) - H(A_1,A_2,B) - H(B).
	\label{eq:conditional_mutual_information}
	\end{equation}

\label{prop:known_entropy_results}
Let $A_1$, $A_2$ be random variables which take values in a finite sets $\mathcal{A}$. 
\begin{enumerate}
\item $H(A_1) \leq \log |\mathcal{A}|$ with equality if and only if $A_1$ is uniformly distributed. 
\item $I(A_1;A_2) \geq 0$ with equality if and only if $A_1$ and $A_2$ are independent.
\item $I(A_1;A_2|B) \geq 0$ with equality if and only if $A_1$ and $A_2$ are independent conditional on $B$. 
\end{enumerate}

