\label{lem:H(X),h(i)}
If $\mathcal{P}$ is a non-trivial protocol on $C_n$ with $s \geq 2$ colours and $X\in_u \mbox{fix}(\mathcal{P})$, then, for all $i$, 
	$$\log_s \mbox{fix}(\mathcal{P}) = H(X), \;\; h(i) \leq 1.$$

We prove this by induction on $(k-j)$. Recall that $h(i_1,i_2,i_3, \ldots ) = H(X_{i_1},X_{i_2},X_{i_3}, \ldots )$.
	\begin{itemize}
	\item {\bf Base case: }$k=j+3$. Since $X_{j+1} = f_{j+1}(X_j,X_{j+2})$ and $X_{j+2} = f_{j+2}(X_{j+1},X_{j+3})$ we have 
		\begin{align*}
		h(j,j+1,j+2) = h(j,j+2) & \leq h(j)+h(j+2) \\ \mbox{and} \qquad 
		h(j+1,j+2,j+3) = h(j+1,j+3) & \leq h(j+1)+h(j+3) ,
		\end{align*}
	respectively. Adding these together yields:
		$$ H_j^{j+3} = h(j,j+1,j+2) + h(j+1,j+2,j+3) \leq h(j)+h(j+1)+h(j+2)+h(j+3). $$
	\item {\bf Inductive step:} $k \geq j+4$. Since $X_{k-1} = f_{k-1}(X_{k-2},X_k)$ we have 
		\begin{align*}
		h(j+1,j+2, \ldots ,k) 
		& = h(j+1,j+2, \ldots ,k-2,k) \\
		& \leq h(j+1,j+2, \ldots ,k-2)+h(k). 
		\end{align*}
	By Proposition~\ref{prop:known_entropy_results}, 
	$ I(X_j ; X_{k-1} | X_{j+1},X_{j+2}, \ldots ,X_{k-2})\geq 0$. Adding these together yields  
		$$ H_j^k \leq H_j^{k-1} + h(k). $$
	This completes the proof. 
	\end{itemize}

