\label{lem:H(X)=sum(H)}
Let $\mathcal{P}$ be a non-trivial protocol on $C_n$ with $s \geq 2$ colours and let $X\in_u \mbox{fix}(\mathcal{P})$. Suppose $1 = d(1),d(2),d(3), \ldots ,d(k) = n$ is a sequence of positive integers with $k \geq 2$. If $d(i+1) \geq d(i)+2$ for all $i$, then 
	$$ 2\log_s\mbox{fix}(\mathcal{P}) = H_{d(1)}^{d(2)} + H_{d(2)+1}^{d(3)} + \cdots + H_{d(k-1)+1}^{d(k)}. $$

\label{defn:P_fcp}
Let $n \geq 3$ be an odd integer, let $s$ be a positive integer, let $a$ be the greatest factor of $s$ less than or equal to $\sqrt{s}$ and let $b = s/a$. For any colouring $c = (c_1,c_2, \ldots ,c_n) \in \mathbb{Z}_s^n$, let $\phi(c_i)$ and $\psi(c_i)$ be referred to as the first and second coordinates respectively of vertex $v_i$. The \emph{fractional-clique-partition protocol} is the protocol $\mathcal{P}_{fcp} = (f_1,f_2, \ldots ,f_n)$ on $C_n$ defined by:
	\begin{align*}
	f_i(c_{i-1},c_{i+1}) & = \pi \big( \phi(c_{i-1}) , \psi(c_{i+1}) \big) & \mbox{for } i=2,4,6, \ldots ,n-1 \\
	f_i(c_{i-1},c_{i+1}) & = \pi \big( \phi(c_{i+1}) , \psi(c_{i-1}) \big) & \mbox{for } i=3,5,7, \ldots ,n-2 \\
	f_1(c_n,c_2) & = \pi \big( \phi(c_2) , \phi(c_n) \big) & \mbox{and} \\
	f_n(c_{n-1},c_1) & = \pi \big( \psi(c_1) (\mbox{mod } a), \psi(c_{n-1}) \big).
	\end{align*}

\begin{align*}
	f_i(c_{i-1},c_{i+1}) & = \pi \big( \phi(c_{i-1}) , \psi(c_{i+1}) \big) & \mbox{for } i=2,4,6, \ldots ,n-1 \\
	f_i(c_{i-1},c_{i+1}) & = \pi \big( \phi(c_{i+1}) , \psi(c_{i-1}) \big) & \mbox{for } i=3,5,7, \ldots ,n-2 \\
	f_1(c_n,c_2) & = \pi \big( \phi(c_2) , \phi(c_n) \big) & \mbox{and} \\
	f_n(c_{n-1},c_1) & = \pi \big( \psi(c_1) (\mbox{mod } a), \psi(c_{n-1}) \big).
	\end{align*}

\label{thm:round_up}
If $n$ is odd and $s = m^2-t$ for integers $m$ and $t \geq 0$ then there exists a protocol $\mathcal{P}$ on $C_n$ with $s$ colours such that 
	$$ \mbox{fix}(\mathcal{P}) \geq s^{n/2} \left( 1 - \frac{tn}{s} \right). $$

\label{defn:semi-perfect_function}
For any $z \in \mathbb{Z}_s$ and for any function $f : \mathbb{Z}_s^2 \rightarrow \mathbb{Z}_s$ let $f^{-1}(z) =  \{ (x,y) \: | \: f(x,y)=z \}$. The function $f$ is called \emph{flat} if and only if $|f^{-1}(z)| = s$ for all $z$. Let $U = (U_1,U_2) \in_u \mathbb{Z}_s^2$. A \emph{semi-perfect} function, $f$, is any flat function such that the $U_1$ and $U_2$ are conditionally independent given $f(U)$ (Definition~\ref{defn:entropy}), \emph{i.e.} 
	$$ I(U_1;U_2 \: | \: f(U)) = 0. $$

\label{defn:(k,e)-uniform} 
For any positive integer $k$ and any $\epsilon >0$, a random variable $Y$ is called $(k,\epsilon)$-uniform if $Y$ takes values in a finite set $\mathcal{Y}$ with $|\mathcal{Y}| = k$ and, for any $y \in \mathcal{Y}$,
	$$ \left| \mathbb{P}(Y=y) - \frac{1}{k} \right| \leq \epsilon .$$

\label{prop:delta}
For any integer $k \geq 2$, any integer $s \geq 2$ and any $\epsilon >0$, there exists $\delta >0$ such that, for any random variable $Y$ which takes $k$ distinct values, if $H(Y)$ is the entropy of $Y$ (base $s$), then 
	$$ H(Y) \geq \log_s k - \delta \qquad \implies \qquad Y \mbox{ is $(k,\epsilon)$-uniform.} $$

\label{lem:shannon}
Let $n \geq 5$ be an integer and let $\mathcal{P}$ be any non-trivial protocol on $C_n$ with $s \geq 2$ colours. The random variables $X_1,X_2,X_3,X_4,X_5$ (Definition~\ref{defn:C_n}) satisfy:
	$$ H_1^5 \leq 3+h(2,4) - I(X_2;X_4|X_3). $$

By Lemma~\ref{lem:H(X),h(i)}, it suffices to show $H_1^5 \leq h(1)+h(3)+h(5)+h(2,4) - I(X_2;X_4|X_3)$. By Shannon's Inequality (Proposition~\ref{prop:known_entropy_results}) we have:
	\begin{align}
	h(2,3,4) + h(3) & = h(2,3) + h(3,4) - I(X_2;X_4|X_3), \label{eq:mutual_information} \\
	h(1,2,3,4) + h(2,3) & \leq h(1,2,3) + h(2,3,4), \label{eq:shannon12} \\
	\mbox{and} \quad h(2,3,4,5) + h(3,4) & \leq h(2,3,4) + h(3,4,5). \label{eq:shannon23} \\
\intertext{Also, since $X_i = f_i(X_{i-1},X_{i+1})$ for $i=2,3,4$ respectively we have:}
	h(1,2,3) &= h(1,3)  \leq h(1) + h(3), \label{eq:func1} \\
	h(2,3,4) & = h(2,4), \label{eq:func2} \\
	\mbox{and} \quad h(3,4,5) &= h(3,5)  \leq h(3) + h(5). \label{eq:func3} 	
	\end{align}
The required result is the sum of equations (\ref{eq:mutual_information}), (\ref{eq:shannon12}), (\ref{eq:shannon23}), (\ref{eq:func1}), (\ref{eq:func2}) and (\ref{eq:func3}).

\begin{align}
	h(2,3,4) + h(3) & = h(2,3) + h(3,4) - I(X_2;X_4|X_3), \label{eq:mutual_information} \\
	h(1,2,3,4) + h(2,3) & \leq h(1,2,3) + h(2,3,4), \label{eq:shannon12} \\
	\mbox{and} \quad h(2,3,4,5) + h(3,4) & \leq h(2,3,4) + h(3,4,5). \label{eq:shannon23} \\
\intertext{Also, since $X_i = f_i(X_{i-1},X_{i+1})$ for $i=2,3,4$ respectively we have:}
	h(1,2,3) &= h(1,3)  \leq h(1) + h(3), \label{eq:func1} \\
	h(2,3,4) & = h(2,4), \label{eq:func2} \\
	\mbox{and} \quad h(3,4,5) &= h(3,5)  \leq h(3) + h(5). \label{eq:func3} 	
	\end{align}

\label{lem:many_non-semi-perfect_functions}
Let $n \geq 7(\delta^{-1}+2)$. Suppose $\mathcal{P} = (f_1,f_2, \ldots ,f_n)$ is a non-trivial protocol on $C_n$ with $s \geq 2$ colours and let $X\in_u \mbox{fix}(\mathcal{P})$ such that, for each $j$, either
	\begin{itemize}
	\item at least one of $f_{j-1}$, $f_j$, $f_{j+1}$ is not semi-perfect, or 
	\item at least one of $(X_{j-2},X_j)$, $(X_{j-1},X_{j+1})$, $(X_j,X_{j+2})$ is not $(s^2,\epsilon)$-uniform,
	\end{itemize}
	  then $\mbox{fix}(\mathcal{P}) < s^{(n-1)/2}$.

\label{defn:perfect_function}
For any function $f: \mathbb{Z}_s^2 \to \mathbb{Z}$, let $L(f,z)$ and $R(f,z)$ denote the subsets 
	\begin{align*} 
	L(f,z) & = \{ x \: | \: f(x,y)=z \mbox{ for some } y \} \\ \mbox{and} \quad  
	R(f,z) & = \{ y \: | \: f(x,y)=z \mbox{ for some } x \}.
	\end{align*}	
The function $f$ is called a \emph{perfect} function if it is semi-perfect and the cardinalities $|L(f,z)|$ and $|R(f,z)|$ do not depend on $z$, 
\emph{i.e.} if $|L(f,z)|=|L(f,z^\prime)|$ and $|R(f,z)|=|R(z^\prime)|$ for all $z,z^\prime \in \mathbb{Z}_s$.

\begin{align*} 
	L(f,z) & = \{ x \: | \: f(x,y)=z \mbox{ for some } y \} \\ \mbox{and} \quad  
	R(f,z) & = \{ y \: | \: f(x,y)=z \mbox{ for some } x \}.
	\end{align*}

\label{lem:two_semi-perfect_functions}
Let $s \geq 2$ be an integer, let $0 <\epsilon  \leq \frac{1}{s^2(2s+1)}$ be a constant. Let $\mathcal{P} = (f_1,f_2, \ldots ,f_n)$ be any non-trivial protocol on $C_n$ with $s$ colours and let $X \in_u \mbox{Fix}(\mathcal{P})$. If $f_1$ and $f_2$ are semi-perfect functions and $(X_0,X_2)$ and $(X_1,X_3)$ are $(s^2,\epsilon)$-uniform, then, for any $c_1,c_2 \in \mathbb{Z}_s$, we have 
	$$ | \{ c_0 | f_1(c_0,c_2)=c_1 \} | = | \{ c_3 | f_2(c_1,c_3)=c_2 \} |. $$

Let $\epsilon$ and $\delta$ be the values given in Definition~\ref{defn:epsilon,delta}, let $N = 7(\delta^{-1}+2)$ and let $\mathcal{P} = (f_1,f_2, \ldots ,f_n)$ be any non-trivial protocol on $C_n$ with $s$ colours. We have two cases:
\begin{description}
\item[Case one] 
	For all $j$, either:
	\begin{itemize} 
	\item at least one of the functions $f_{j-1}$, $f_j$ and $f_{j+1}$ is not semi-perfect or 
	\item at least one of $(X_{j-2},X_j)$, $(X_{j-1},X_{j+1})$, $(X_j,X_{j+2})$ is not $(s^2,\epsilon)$-uniform. 
	\end{itemize}
\item[Case two] 
	There exists some $j$ such that: 
	\begin{itemize}
	\item the functions $f_{j-1}$, $f_j$ and $f_{j+1}$ are all semi-perfect and 
	\item $(X_{j-2},X_j)$, $(X_{j-1},X_{j+1})$ and $(X_j,X_{j+2})$ are all $(s^2,\epsilon)$-uniform.
	\end{itemize}
\end{description}
For case one, we can conclude that $\mbox{fix}(\mathcal{P}) \leq s^{(n-1)/2} \leq \mbox{fix}(\mathcal{P}_{fcp})$ by Lemma~\ref{lem:many_non-semi-perfect_functions}. In case two, $f_j$ must be a perfect function (Lemma~\ref{lem:three_semi-perfect_functions}) and then $\mbox{fix}(\mathcal{P}) \leq as^{(n-1)/2} = \mbox{fix}(\mathcal{P}_{fcp})$ (Lemma~\ref{lem:one_perfect_function}). In either case, $\mbox{fix}(\mathcal{P}_{fcp}) \geq \mbox{fix}(\mathcal{P})$. Hence $\mathcal{P}_{fcp}$ is optimal.

\label{thm:defective}
For a given $s$, let $b$ be the smallest factor of $s$ which is at least $\sqrt{s}$. There exists some $N$ such that for all odd $n>N$, 
	$$ \beta(C_n,s) = \frac{n-1}{2} + \log_sb. $$
